"""Generate the dependency-free site. Run from any directory with Python 3."""
from pathlib import Path
from html import escape
import json
import re
import hashlib

ROOT = Path(__file__).resolve().parents[1]
BASE = 'https://lukebrennan.github.io/Maeve-Arden-Photography/'
LOGO_VERSION = hashlib.sha256((ROOT/'assets/icons/logo-mark.svg').read_bytes()).hexdigest()[:8]
FAVICON_VERSION = hashlib.sha256((ROOT/'assets/icons/favicon.svg').read_bytes()).hexdigest()[:8]

# Keep the maintained CSS readable and the served stylesheet compact.
css_source = (ROOT / 'src/style.css').read_text()
css = re.sub(r'/\*.*?\*/', '', css_source, flags=re.S)
css = re.sub(r'\s+', ' ', css)
css = re.sub(r'\s*([{};])\s*', r'\1', css).strip()
(ROOT / 'assets/css/style.css').write_text(css+'\n')
PHOTOS = {
    'hero': ('Bride and groom sharing a laugh on their wedding day', 'Rafa Sanfilippo', 'cWLEzYAcI3Q'),
    'still-water': ('Newlyweds standing together at the end of a wooden jetty', 'Sabesh Photography LTD', 'gpGfPhSr3rQ'),
    'city-softened': ('Bridal portrait beneath the arches of Tower Bridge in London', 'Howard Walsh', 'P_jDtRMQxL0'),
    'celebration': ('Bride and groom surrounded by a shower of confetti', 'Ben Atkins', 'CkQxfER9FvA'),
    'bridal': ('Bridal portrait in soft black and white light', 'Alexander Mass', 'HVTDyWXQkrA'),
    'table': ('Wedding reception table with flowers and candlelight', 'Ben Atkins', 'zjJiX9txwRU'),
    'lake-sunset': ('Newlyweds beside a still lake at sunset', 'c k', 'o6u_mqxYGDg'),
    'evening': ('Wedding couple embraced in dramatic evening light', 'Foto Pettine', 'AXaQzYRIb4w'),
}

def picture(key, prefix='', sizes='100vw', eager=False, cls=''):
    alt = PHOTOS[key.replace('-landscape', '')][0]
    manifest = ROOT / 'assets/images/manifest.json'
    dims = json.loads(manifest.read_text()).get(key, {}) if manifest.exists() else {}
    # The aspect ratio of the box is controlled by CSS; these describe the file.
    width = dims.get('width', dims.get('original_width', 1600))
    height = dims.get('height', dims.get('original_height', 2000))
    widths = (480, 800, 1200, 1600)
    path = f'{prefix}assets/images/{key}'
    avif = ', '.join(f'{path}-{w}.avif {w}w' for w in widths)
    webp = ', '.join(f'{path}-{w}.webp {w}w' for w in widths)
    priority = 'fetchpriority="high" loading="eager"' if eager else 'loading="lazy"'
    return f'<picture class="{cls}"><source type="image/avif" srcset="{avif}" sizes="{sizes}"><img src="{path}-800.webp" srcset="{webp}" sizes="{sizes}" width="{width}" height="{height}" alt="{alt}" {priority} decoding="async"></picture>'

def arrow():
    return '<span aria-hidden="true">↗</span>'

def brand(prefix=''):
    return f'<a class="brand" href="{prefix}index.html" aria-label="Maeve Arden Photography home"><img src="{prefix}assets/icons/logo-mark.svg?v={LOGO_VERSION}" width="38" height="38" alt=""><span><span class="brand-name">Maeve Arden</span><span class="brand-sub">Photography</span></span></a>'

def nav(prefix, active, mobile=False):
    links = [('portfolio', 'Selected work'), ('weddings', 'The experience'), ('about', 'About'), ('journal', 'Journal')]
    return ''.join(f'<a href="{prefix}{slug}.html"'+(' aria-current="page"' if slug == active else '')+f'>{label}</a>' for slug, label in links)

def header(prefix, active):
    return f'''<a class="skip-link" href="#main">Skip to content</a>
<header class="site-header"><noscript><style>.desktop-nav{{display:flex;flex-wrap:wrap}}.menu-toggle{{display:none}}.header-inner{{flex-wrap:wrap;padding-block:16px}}</style></noscript><div class="header-inner">{brand(prefix)}<nav class="desktop-nav" aria-label="Main navigation">{nav(prefix, active)}<a class="button button-small" href="{prefix}contact.html">Check your date {arrow()}</a></nav><button class="menu-toggle" type="button" aria-label="Open navigation" aria-haspopup="dialog" aria-controls="navigation-dialog" aria-expanded="false" data-menu-open><span>Menu</span><svg width="20" height="16" viewBox="0 0 20 16" aria-hidden="true"><path d="M1 4h18M1 12h18" stroke="currentColor" stroke-width="1.5"/></svg></button></div></header>
<dialog id="navigation-dialog" class="navigation-dialog" aria-labelledby="navigation-title"><div class="menu-head"><h2 id="navigation-title">Explore Maeve Arden</h2><button class="icon-button" type="button" data-menu-close aria-label="Close navigation">×</button></div><nav aria-label="Mobile navigation">{nav(prefix, active)}<a href="{prefix}contact.html">Check your date {arrow()}</a></nav><p class="eyebrow">Lake District · UK · Europe</p></dialog>'''

def footer(prefix):
    return f'''<footer class="site-footer"><div class="container"><div class="footer-top">{brand(prefix)}<p>A quiet eye. An honest story.<br>Editorial wedding photography, UK & Europe.</p><nav aria-label="Footer navigation"><a href="{prefix}portfolio.html">Selected work</a><a href="{prefix}weddings.html">Collections</a><a href="{prefix}contact.html">Enquire {arrow()}</a></nav></div><div class="footer-bottom"><p>© <span data-year>2026</span> Maeve Arden</p><p>A fictional brand & website concept by <a href="https://github.com/lukebrennan">Luke Brennan</a>.</p><div><a href="{prefix}credits.html">Image credits</a><a href="{prefix}privacy.html">Privacy</a></div></div></div></footer>'''

def lightbox(prefix):
    return f'''<dialog class="lightbox" data-lightbox-dialog aria-labelledby="lightbox-title"><div class="lightbox-top"><div><p class="eyebrow">Selected photographs</p><h2 id="lightbox-title">Photograph</h2></div><button class="icon-button" type="button" data-lightbox-close aria-label="Close photograph">×</button></div><div class="lightbox-image"><img data-lightbox-image alt="" width="1600" height="2000"></div><div class="lightbox-bottom"><a data-lightbox-credit href="{prefix}credits.html">Image credit</a><div class="lightbox-controls"><button class="icon-button" type="button" data-lightbox-prev aria-label="Previous photograph">←</button><span data-lightbox-count aria-live="polite"></span><button class="icon-button" type="button" data-lightbox-next aria-label="Next photograph">→</button></div></div></dialog>'''

def cta(prefix='', label='Let’s start with your date.'):
    return f'''<section class="closing-cta"><div class="container"><div><p class="eyebrow">Something worth remembering</p><h2>{label}</h2><p>A place, a date, a little about the two of you.</p></div><a class="button button-light" href="{prefix}contact.html">Check your date {arrow()}</a></div></section>'''

PAGES = []
def page(path, title, desc, body, active='', image='hero', kind='WebPage', crumbs=None, lightbox_needed=False):
    prefix = '../' * path.count('/')
    url = BASE + ('' if path == 'index.html' else path)
    title = title + ' | Maeve Arden Photography'
    graph = [{ '@type':'WebSite', '@id': BASE+'#website', 'url':BASE, 'name':'Maeve Arden Photography', 'description':'An editorial wedding photography website concept by Luke Brennan.' },
             {'@type':kind, '@id':url+'#page', 'name':title, 'description':desc, 'url':url, 'isPartOf':{'@id':BASE+'#website'}}]
    if crumbs:
        graph.append({'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':i+1,'name':name,'item':BASE+slug} for i,(name,slug) in enumerate([('Home','')]+crumbs)]})
    if kind == 'Article':
        graph[1].update({'headline':title.split(' | ')[0], 'image':BASE+'assets/images/social.jpg', 'author':{'@type':'Person','name':'Luke Brennan','url':'https://github.com/lukebrennan'}})
    robots = 'noindex,follow' if path == '404.html' else 'index,follow,max-image-preview:large'
    preload = f'<link rel="preload" as="image" type="image/avif" href="{prefix}assets/images/hero-landscape-800.avif" imagesrcset="{prefix}assets/images/hero-landscape-480.avif 480w, {prefix}assets/images/hero-landscape-800.avif 800w, {prefix}assets/images/hero-landscape-1200.avif 1200w, {prefix}assets/images/hero-landscape-1600.avif 1600w" imagesizes="(max-width: 760px) calc(100vw - 40px), 55vw" fetchpriority="high">' if path=='index.html' else ''
    html = f'''<!doctype html>
<html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)}</title><meta name="description" content="{escape(desc, quote=True)}"><meta name="robots" content="{robots}"><meta name="theme-color" content="#f7f5ef"><link rel="canonical" href="{url}"><meta property="og:type" content="{'article' if kind=='Article' else 'website'}"><meta property="og:title" content="{escape(title, quote=True)}"><meta property="og:description" content="{escape(desc, quote=True)}"><meta property="og:url" content="{url}"><meta property="og:image" content="{BASE}assets/images/social.jpg"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="Bride and groom laughing together — Maeve Arden Photography concept"><meta property="og:locale" content="en_GB"><meta name="twitter:card" content="summary_large_image"><link rel="icon" type="image/svg+xml" href="{prefix}assets/icons/favicon.svg?v={FAVICON_VERSION}"><link rel="manifest" href="{prefix}site.webmanifest">{preload}<link rel="stylesheet" href="{prefix}assets/css/style.css"><script type="application/ld+json">{json.dumps({'@context':'https://schema.org','@graph':graph}, ensure_ascii=False)}</script><script src="{prefix}assets/js/main.js" defer></script></head><body data-asset-prefix="{prefix}">{header(prefix,active)}<main id="main" tabindex="-1">{body}</main>{footer(prefix)}{lightbox(prefix) if lightbox_needed else ''}{'<a class="mobile-enquire" href="'+prefix+'contact.html">Check your date '+arrow()+'</a>' if active!='contact' else ''}</body></html>'''
    if path == '404.html':
        # GitHub serves 404.html at arbitrary nested URLs. Keep the error page
        # self-contained and point recovery links at the real project root.
        html = html.replace(f'<link rel="stylesheet" href="{prefix}assets/css/style.css">', '<style>'+css+'</style>')
        html = re.sub(r'<script src="[^"]+" defer></script>', '', html)
        html = re.sub(r'<header class="site-header">.*?</header>', f'<header class="site-header"><div class="header-inner"><a class="brand" href="{BASE}"><span><span class="brand-name">Maeve Arden</span><span class="brand-sub">Photography</span></span></a><a class="text-link" href="{BASE}">Home ↗</a></div></header>', html)
        html = re.sub(r'<dialog id="navigation-dialog".*?</dialog>', '', html)
        html = re.sub(r'<footer class="site-footer">.*?</footer>', '<footer class="site-footer"><div class="container footer-bottom"><p>A fictional brand & website concept by Luke Brennan.</p><a href="'+BASE+'credits.html">Image credits</a></div></footer>', html)
        html = re.sub(r'<a class="mobile-enquire".*?</a>', '', html)
        html = re.sub(r'href="(?!https?:|#)([^"]+)"', lambda match:'href="'+BASE+match.group(1)+'"', html)
    target = ROOT/path
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(html, encoding='utf-8')
    if path != '404.html':
        PAGES.append(url)

def intro(eyebrow, heading, desc='', prefix='', crumb=None):
    breadcrumb = f'<nav class="breadcrumbs" aria-label="Breadcrumb"><a href="{prefix}index.html">Home</a><span aria-hidden="true">/</span><span>{crumb}</span></nav>' if crumb else ''
    return f'<section class="page-intro container">{breadcrumb}<p class="eyebrow">{eyebrow}</p><h1>{heading}</h1>'+ (f'<p class="intro-summary">{desc}</p>' if desc else '') + '</section>'

def workcard(key, name, subtitle, number, href, cls=''):
    return f'<a class="work-card {cls}" href="{href}"><div class="work-image">{picture(key,sizes="(max-width: 760px) calc(100vw - 40px), 32vw")}<span class="image-action">Explore story {arrow()}</span></div><div class="work-caption"><div><span class="eyebrow">{subtitle}</span><h3>{name}</h3></div><span class="work-number">{number} {arrow()}</span></div></a>'

def journalcard(key, category, title, href, length):
    return f'<a class="journal-card" href="{href}"><div class="journal-image">{picture(key,sizes="(max-width: 760px) calc(100vw - 40px), 32vw")}</div><div class="journal-meta"><span class="eyebrow">{category} · {length} min read</span><h3>{title}</h3><span class="text-link">Read the notes {arrow()}</span></div></a>'

home = f'''<section class="home-hero container"><div class="hero-copy"><p class="eyebrow"><span class="status-dot" aria-hidden="true"></span> Wedding & editorial photographer</p><h1>Your day.<br><em>Beautifully real.</em></h1><p class="hero-summary">Honest moments. A considered eye.<br>Wedding photography with feeling, across<br class="desktop-break"> the Lake District, UK and Europe.</p><div class="hero-actions"><a class="button" href="contact.html">Check your date {arrow()}</a><a class="text-link" href="portfolio.html">View portfolio {arrow()}</a></div><div class="hero-facts"><div><span>Based in</span><strong>The Lake District</strong></div><div><span>Wedding collections</span><strong>From £2,850</strong></div></div></div><div class="hero-visual"><div class="hero-image">{picture('hero-landscape',sizes='(max-width: 760px) calc(100vw - 40px), 55vw',eager=True)}</div><div class="hero-image-note"><span>01 / A little less posing. A little more living.</span></div><div class="hero-inset">{picture('table',sizes='(max-width: 760px) 130px, 180px')}<span>The details.<br>The feeling.<br>The whole story.</span></div></div></section>
<section class="approach-strip container" aria-label="The approach"><p>Editorial eye.<br><em>Documentary heart.</em></p><div><span>01</span><p>Calm direction<br><small>Space to feel like yourselves.</small></p></div><div><span>02</span><p>Honest storytelling<br><small>The small moments belong, too.</small></p></div><div><span>03</span><p>A personal experience<br><small>From first hello to final gallery.</small></p></div></section>
<section class="section container" aria-labelledby="selected-title"><div class="section-heading"><div><p class="eyebrow">01 / Selected stories</p><h2 id="selected-title">A feeling, <em>held in a frame.</em></h2></div><a class="text-link" href="portfolio.html">View all photographs {arrow()}</a></div><div class="work-grid">{workcard('still-water','Still Water','Waterside · Visual study','01','stories/still-water.html')}{workcard('city-softened','City, Softened','London · Visual study','02','stories/city-softened.html','offset')}{workcard('celebration','After the Quiet','Celebration · Visual study','03','stories/after-the-quiet.html')}</div></section>
<section class="experience-section" aria-labelledby="experience-title"><div class="container experience-grid"><div class="experience-image">{picture('bridal',sizes='(max-width: 760px) calc(100vw - 40px), 42vw')}<span class="image-caption">Quietly considered. Never overproduced.</span></div><div class="experience-copy"><p class="eyebrow">02 / The experience</p><h2 id="experience-title">Be in the moment.<br><em>I’ll take care of the memories.</em></h2><p>You deserve to enjoy your wedding. A little planning, a little guidance, and plenty of room for the day to unfold in its own way.</p><div class="experience-point"><span>01</span><div><h3>Before the day</h3><p>We talk through what matters and build a relaxed photography plan around it.</p></div></div><div class="experience-point"><span>02</span><div><h3>In the moment</h3><p>Useful direction when you need it. An unobtrusive presence when you don’t.</p></div></div><div class="experience-point"><span>03</span><div><h3>For the years ahead</h3><p>A thoughtful, complete story, ready to revisit, print and share.</p></div></div><a class="text-link" href="weddings.html">Explore the experience & collections {arrow()}</a></div></div></section>
<section class="section container" aria-labelledby="journal-title"><div class="section-heading"><div><p class="eyebrow">03 / Field notes</p><h2 id="journal-title">A little inspiration.<br><em>A few useful things.</em></h2></div><a class="text-link" href="journal.html">From the journal {arrow()}</a></div><div class="journal-grid">{journalcard('still-water','Places','Making room for the Lake District','journal/lake-district-wedding-photography.html',3)}{journalcard('table','Planning','Editorial photographs, naturally','journal/editorial-wedding-photographs.html',2)}{journalcard('city-softened','City weddings','Finding a quiet moment in London','journal/london-wedding-portraits.html',2)}</div></section>{cta()}'''
page('index.html','Editorial Wedding Photographer, UK & Europe','Natural wedding photography with an editorial finish. Explore the Maeve Arden portfolio concept, collections and relaxed approach across the Lake District, UK and Europe.',home)

gallery_items = [('still-water','Still Water','places'),('hero','Beautifully Real','celebrations'),('bridal','Quiet Light','portraits'),('city-softened','City, Softened','places'),('table','At the Table','details'),('celebration','After the Quiet','celebrations'),('lake-sunset','Last Light','places'),('evening','Just the Two of You','portraits')]
