portfolio = intro('A considered collection','The moments.<br><em>The feeling in between.</em>','People, place and the little things that make a day its own. Explore the photographs, or step into one of the visual stories below.',crumb='Selected work') + f'''<section class="container gallery-section" aria-label="Photography portfolio"><div class="gallery-toolbar" data-gallery-toolbar hidden><div class="gallery-filters" role="group" aria-label="Filter photographs">{''.join(f'<button type="button" data-filter="{value}" aria-pressed="{str(value=="all").lower()}">{label}</button>' for value,label in [('all','All work'),('celebrations','Celebrations'),('portraits','Portraits'),('places','Places'),('details','Details')])}</div><p data-gallery-status role="status">8 photographs</p></div><div class="gallery-grid">{tiles}</div><p class="small-note">A curated collection of stock photography for this website concept. <a href="credits.html">Meet the photographers {arrow()}</a></p></section><section class="section container"><div class="section-heading"><div><p class="eyebrow">Explore a little further</p><h2>Three visual stories.</h2></div></div><div class="work-grid">{workcard('still-water','Still Water','Waterside · Visual study','01','stories/still-water.html')}{workcard('city-softened','City, Softened','London · Visual study','02','stories/city-softened.html')}{workcard('celebration','After the Quiet','Celebration · Visual study','03','stories/after-the-quiet.html')}</div></section>{cta()}'''
