weddings = intro('The experience & collections','Live the day.<br><em>Keep the feeling.</em>','Editorial in feel, documentary at heart. Thoughtful coverage that makes room for your people, your plans and everything in between.',crumb='The experience')+f'''<div class="container wide-photo">{picture('celebration',sizes='(max-width: 760px) calc(100vw - 40px), 90vw',eager=True)}</div><section class="section container" id="collections" aria-labelledby="collections-title"><div class="section-heading"><div><p class="eyebrow">Your day, your collection</p><h2 id="collections-title">Simple, considered coverage.</h2></div><p>Planning support, thoughtful editing and a private gallery come with every collection.</p></div><div class="pricing-grid">{prices}</div><p class="small-note">Illustrative collections for this portfolio concept. Destination travel and any additions would be confirmed in a personal quote.</p></section><section class="experience-section" id="destinations"><div class="container split-story"><div>{picture('lake-sunset',sizes='(max-width: 760px) calc(100vw - 40px), 47vw')}</div><div><p class="eyebrow">Somewhere a little further</p><h2>A familiar presence.<br><em>An unforgettable place.</em></h2><p>For weddings in Italy and across Europe, make space for the whole celebration. A welcome evening, the wedding day, perhaps a quiet morning after.</p><a class="text-link" href="contact.html?collection=destination">Talk about a destination wedding {arrow()}</a></div></div></section><section class="section container faq-section" aria-labelledby="faq-title"><div><p class="eyebrow">A few things you might wonder</p><h2 id="faq-title">Before you enquire.</h2><p>More about the approach and what happens next.</p></div><div class="faq-list">{''.join(f'<details><summary>{q}<span aria-hidden="true">+</span></summary><p>{a}</p></details>' for q,a in faqs)}</div></section>{cta()}'''
page('weddings.html','Wedding Collections & Experience','Explore relaxed wedding photography collections, intimate celebrations and destination coverage in the Maeve Arden website concept. Full-day collections from £2,850.',weddings,active='weddings',crumbs=[('The experience','weddings.html')],image='celebration')

about = intro('A quiet eye for an honest story','There’s beauty<br><em>in being yourselves.</em>','The best photographs take you back to how it felt. The wind, the laughter, the people. All of it.',crumb='About')+f'''<section class="container about-layout"><div class="about-image">{picture('evening',sizes='(max-width: 760px) calc(100vw - 40px), 47vw',eager=True)}<span class="image-caption">A little space to let the day be yours.</span></div><div class="about-copy"><p class="eyebrow">Meet the approach</p><h2>Part observer.<br>Part director.<br><em>Always present.</em></h2><p>Maeve Arden’s world is quietly editorial: considered composition, beautiful light and photographs that still feel like you.</p><p>The approach brings people and place together. Help when direction is useful, space when it isn’t, and attention to the gestures and glances that make a story personal.</p><p>From a lakeside celebration to a city wedding, the idea is the same: plan carefully, guide lightly, and leave room for life.</p><a class="text-link" href="weddings.html">Discover the experience {arrow()}</a></div></section><section class="section container"><div class="values-grid"><article><p class="eyebrow">01 / Elegant</p><h2>A considered eye.</h2><p>Beautiful light and intentional composition, with an editorial finish that feels natural.</p></article><article><p class="eyebrow">02 / Honest</p><h2>A personal story.</h2><p>Real expressions and movement. The photographs that feel like you, long after trends pass.</p></article><article><p class="eyebrow">03 / Alive</p><h2>Room for the unexpected.</h2><p>The laughter after a portrait. A veil caught in the wind. A hand squeezed under the table.</p></article></div></section><section class="concept-note container"><p class="eyebrow">Behind the concept</p><h2>Made with care, by Luke Brennan.</h2><p>Maeve Arden is a fictional photography brand created to explore thoughtful web design: an image-led identity, an accessible gallery, a clear enquiry journey and a fast, lightweight website. Every photograph is credited to its original creator.</p><a class="text-link" href="credits.html">Meet the photographers {arrow()}</a></section>{cta()}'''
page('about.html','About the Editorial Photography Approach','Discover the quiet editorial approach behind Maeve Arden, a fictional photography brand and carefully crafted website portfolio concept by Luke Brennan.',about,active='about',crumbs=[('About','about.html')],image='evening')

journal = intro('Field notes','A little perspective.<br><em>A little inspiration.</em>','Useful thoughts on light, place and making room for photographs without losing the day.',crumb='Journal')+f'''<section class="container journal-list" aria-label="Journal articles"><div class="journal-grid">{journalcard('still-water','Places','Making room for the Lake District','journal/lake-district-wedding-photography.html',3)}{journalcard('table','Planning','Editorial photographs, naturally','journal/editorial-wedding-photographs.html',2)}{journalcard('city-softened','City weddings','Finding a quiet moment in London','journal/london-wedding-portraits.html',2)}</div></section>{cta()}'''
page('journal.html','Wedding Planning Notes & Inspiration','Wedding photography planning notes from the Maeve Arden concept: the Lake District, natural editorial photographs and relaxed London wedding portraits.',journal,active='journal',kind='CollectionPage',crumbs=[('Journal','journal.html')])

articles = [
('lake-district-wedding-photography','Making room for the Lake District','Places','still-water',3,'Water, woodland, stone and changing light. Make the landscape part of the day without making it the whole day.',[
('Let the weather into the story','Low cloud, a breeze and a little rain can give photographs texture and atmosphere. Build a practical fallback into your plans: a sheltered spot, somewhere with good window light, and shoes that can cope with the ground. The aim is flexibility, so a change in weather doesn’t take over the day.'),
('Keep an evening window flexible','A short break for portraits can be enough. Rather than disappearing for an hour, leave a little room in the schedule to step outside when the light works. Talk through that possibility beforehand, and keep dinner, speeches and your guests at the centre of the plan.'),
('Think beyond the big view','The setting can appear quietly: reflections, wet foliage, old stone, a line of trees. Mixing wider views with close portraits and small details creates a varied story. You don’t need to chase every landmark to make the photographs feel rooted in a place.'),
('Look for variety close to the venue','When choosing a venue, think about covered areas, accessible paths and indoor light as well as the ceremony space. Nearby options make it easier to adapt without spending your wedding day travelling between locations. Ask your venue about access and permissions before planning a lakeside route.'),
('Keep the day yours','The photographs should fit around the celebration. Plan the important group pictures, share any access needs, and leave space for the spontaneous moments. The landscape is a wonderful backdrop, but the people are the story.')]),
('editorial-wedding-photographs','Editorial photographs, naturally','Planning','table',2,'A considered photograph can still feel spontaneous. A few thoughtful choices make that balance easier.',[
('Give good light a little room','For preparations, a calm spot near a window often gives you more options than a crowded corner under ceiling lights. Clear a little space beforehand, then let the morning happen. You don’t need to stage the entire room.'),
('Choose movement over performance','Walking together, talking and taking a moment to breathe give portraits life. Simple direction can help you feel comfortable without prescribing every expression. Share what feels natural to you and what you would rather avoid.'),
('Plan the essentials, then let go','Write down the family groups you care about and agree a realistic time for them. Keep the list focused. Once those essentials are covered, there is more space for photographs of the conversations, gestures and energy that can’t be planned.'),
('Let the details belong to the day','A beautiful table matters because people will gather around it. Photograph the design and the atmosphere around it: hands reaching for glasses, flowers in changing light, a room beginning to fill. The details become richer when they connect to the people.'),
('Talk about what matters','Tell your photographer what you hope to remember, not just which photographs you have seen online. A person, a feeling, a tradition or a quiet moment can be a more useful starting point than a long list of poses.')]),
('london-wedding-portraits','Finding a quiet moment in London','City weddings','city-softened',2,'City texture, a little movement and somewhere to pause. Portraits can be part of the journey, rather than a long detour.',[
('Keep the route short','Choose one or two portrait locations near your venue, then plan a simple route. Long journeys can quickly eat into a wedding schedule. A doorway, a stretch of pavement or a sheltered courtyard may be all you need.'),
('Look for calm within the city','Interesting light and texture are often more useful than a recognisable landmark. Look for open shade, pale stone, reflections and quiet corners. A place you can enjoy for a few minutes is more valuable than a busy backdrop you have to fight.'),
('Check access before the day','A public-looking space may still have photography restrictions. Confirm access with the venue or landowner, especially for indoor locations or a larger setup. Keep a nearby alternative so one unavailable spot doesn’t upset the plan.'),
('Make room for the unexpected','Traffic, crowds and weather can change the feel of a route. Build in a little breathing room and keep the plan adaptable. If a location is crowded, use a closer frame, move to a quieter corner, or return to the venue.'),
('Stay connected to the celebration','Portraits can be a brief pause together before you return to your guests. Agree a comfortable amount of time in advance. The city gives you the setting; your connection gives the photographs their meaning.')])]
for slug,title,category,key,length,lede,sections in articles:
    content = f'''<section class="article-heading container"><nav class="breadcrumbs" aria-label="Breadcrumb"><a href="../index.html">Home</a><span aria-hidden="true">/</span><a href="../journal.html">Journal</a></nav><p class="eyebrow">{category} · {length} min read</p><h1>{title}</h1><p class="intro-summary">{lede}</p></section><figure class="container article-cover">{picture(key,prefix='../',sizes='(max-width: 760px) calc(100vw - 40px), 90vw',eager=True)}<figcaption>Photograph by {PHOTOS[key][1]}. <a href="../credits.html">Image credits</a></figcaption></figure><div class="container article-layout"><aside class="article-toc"><p class="eyebrow">In these notes</p><nav aria-label="Article sections">{''.join(f'<a href="#note-{i}">{heading}</a>' for i,(heading,text) in enumerate(sections))}</nav></aside><article class="article-body">{''.join(f'<section id="note-{i}"><h2>{heading}</h2><p>{text}</p></section>' for i,(heading,text) in enumerate(sections))}<div class="article-next"><p class="eyebrow">The next step</p><h2>Make room for your story.</h2><p>Explore the collections or share a little about your plans.</p><a class="text-link" href="../weddings.html">Explore the experience {arrow()}</a></div></article></div><section class="section container"><div class="section-heading"><div><p class="eyebrow">Continue exploring</p><h2>More from the field notes.</h2></div><a class="text-link" href="../journal.html">All notes {arrow()}</a></div><div class="journal-grid">{''.join(journalcard(other[3],other[2],other[1],other[0]+'.html',other[4]).replace('assets/images/','../assets/images/') for other in articles if other[0]!=slug)}</div></section>{cta('../')}'''
    page('journal/'+slug+'.html',title,lede,content,active='journal',image=key,kind='Article',crumbs=[('Journal','journal.html'),(title,'journal/'+slug+'.html')])

stories=[('still-water','Still Water','A waterside study','still-water',['still-water','lake-sunset','evening'],'Still water, soft light and a little space to breathe. A study in people and place.'),('city-softened','City, Softened','An urban study','city-softened',['city-softened','bridal','table'],'London in the background. The two of you in the foreground. A study in texture and quiet moments.'),('after-the-quiet','After the Quiet','A celebration study','celebration',['celebration','hero','table'],'The confetti, the laughter, the room coming alive. A study in the energy of a celebration.')]
